def create_histogram(objects, attribute, num_bins=NUM_BINS, title=None):
    """
    Create a histogram of the specified attribute from a list of objects and return the plotly Figure.

    - objects: iterable of objects. Each object can be:
        - a mapping (dict-like) and attribute is a key (string), or
        - a Python object and attribute is an attribute name (string), or
        - if attribute is callable, it will be called as attribute(obj) to get the value.
    - attribute: str (attribute name / dict key) or callable(obj) -> value
    - num_bins: number of histogram bins (default NUM_BINS)
    - title: optional plot title

    Returns:
    - plotly.graph_objects.Figure (a histogram)

    Requires: plotly (plotly.express).
    Example:
        figs = create_histogram(users, "age")
        figs.show()
    """
    # Local import to keep function self-contained
    import plotly.express as px
    import math

    if objects is None:
        raise ValueError("objects must be an iterable (not None).")

    # prepare accessor
    if callable(attribute):
        accessor = attribute
    elif isinstance(attribute, str):
        def accessor(obj):
            # try mapping access first (dict-like)
            try:
                if hasattr(obj, "get") and callable(getattr(obj, "get")):
                    # dict or dict-like
                    if attribute in obj:
                        return obj.get(attribute)
                # try attribute access
                return getattr(obj, attribute)
            except Exception:
                # fallback: try mapping access with [] (for e.g., dicts that don't have get)
                try:
                    return obj[attribute]
                except Exception:
                    raise AttributeError(f"Object {obj!r} has no attribute/key '{attribute}'")
    else:
        raise TypeError("attribute must be a string (attribute/key name) or a callable(obj) -> value")

    # extract values
    values = []
    seen_any = False
    for obj in objects:
        seen_any = True
        try:
            v = accessor(obj)
        except AttributeError:
            # skip objects without the attribute/key
            continue
        # convert to numeric if possible, ignore None
        if v is None:
            continue
        # If it's already a number (int/float), accept it (but filter nan/inf)
        if isinstance(v, (int, float)):
            if isinstance(v, float) and (math.isinf(v) or math.isnan(v)):
                continue
            values.append(v)
            continue
        # try converting numeric strings
        try:
            vf = float(v)
            if math.isinf(vf) or math.isnan(vf):
                continue
            values.append(vf)
        except Exception:
            # non-numeric value: skip
            continue

    if not seen_any:
        raise ValueError("objects iterable appears empty.")
    if len(values) == 0:
        raise ValueError("No numeric values found for the specified attribute.")

    # build histogram with plotly express
    fig = px.histogram(x=values, nbins=num_bins, title=title or f"Histogram of '{attribute}'")
    fig.update_layout(xaxis_title=str(attribute), yaxis_title="count")
    return fig

