def replace_random_substring(strings):
    def generate_random_string(length):
        return ''.join(random.choices(string.ascii_lowercase, k=length))

    def replace_substring(s):
        # Find all substrings between commas or at the beginning/end of the string
        substrings = []
        start = 0
        while start < len(s):
            if s[start] == ',':
                end = s.find(',', start + 1)
                if end == -1:
                    end = len(s)
                substrings.append(s[start:end])
                start = end + 1
            else:
                end = s.find(',', start)
                if end == -1:
                    end = len(s)
                substrings.append(s[start:end])
                start = end + 1

        # Replace each substring with a random string of the same length
        for i in range(len(substrings)):
            length = len(substrings[i])
            random_string = generate_random_string(length)
            substrings[i] = random_string

        # Reconstruct the string
        result = ''
        start = 0
        for substring in substrings:
            result += substring
            if start < len(s) and s[start] == ',':
                result += ','
            start += len(substring)

        return result

    return [replace_substring(s) for s in strings]

