        (which is a subclass of datetime.datetime with tzinfo).

    Returns
    - str or datetime.datetime depending on return_type.

    Notes
    - Requires the pendulum library (install with: pip install pendulum).
    - pendulum is actively maintained and provides robust timezone handling.
    """
    import datetime
    import pendulum

    # validate timezone names early
    try:
        pendulum.timezone(from_tz)
        pendulum.timezone(to_tz)
    except Exception as e:
        raise ValueError(f"Invalid timezone name: {e}") from e

    # Parse / normalize input into a pendulum.DateTime
    if isinstance(dt_input, str):
        try:
