                # from_format accepts a tz parameter
                dt = pendulum.from_format(dt_input, fmt, tz=from_tz)
            else:
                dt = pendulum.parse(dt_input, tz=from_tz)
        except Exception as e:
            raise ValueError(f"Could not parse datetime string: {e}") from e
    elif isinstance(dt_input, datetime.datetime):
