            if dt_input.tzinfo is None:
                dt = pendulum.instance(dt_input, tz=from_tz)
            else:
                dt = pendulum.instance(dt_input)
        except Exception as e:
            raise ValueError(f"Could not convert datetime instance: {e}") from e
    else:
        # attempt to coerce other datetime-like objects
        try:
            dt = pendulum.instance(dt_input)
        except Exception:
            raise TypeError("dt_input must be a string or a datetime.datetime (or a pendulum.DateTime)")

    # Convert timezone
    try:
        converted = dt.in_timezone(to_tz)
    except Exception as e:
        raise ValueError(f"Timezone conversion failed: {e}") from e

