def export_function_specs_to_csv(f_list, file_path):
    """
    Export specifications of functions in `f_list` to a CSV file at `file_path`.

    CSV columns:
    - 'Function Name': The name of the function.
    - 'Number of Arguments': Number of function parameters (excludes *args and **kwargs).
    - 'Defaults': Dict of parameter default values (param name -> repr(default)).
    - 'Annotations': Dict of parameter and return annotations (param name -> stringified annotation, and 'return' -> return annotation if present).
    - 'Is Lambda': True if the function is a lambda (name == '<lambda>').

    Notes:
    - Non-callable items in f_list are ignored.
    - Uses the polars library (popular DataFrame library). If polars is not installed,
      install it with: pip install polars
    """
    import inspect
    import json

    try:
        import polars as pl
    except ImportError as e:
        raise ImportError(
            "polars is required for this function. Install with: pip install polars"
        ) from e

    rows = []
    for f in f_list:
        if not callable(f):
            # skip non-callables
            continue

        # function name (fallback to repr if name not present)
        name = getattr(f, "__name__", None) or repr(f)

        # signature and parameters
        try:
            sig = inspect.signature(f)
        except (ValueError, TypeError):
            # some callables (builtins, C extensions) may not have a signature
            # fallback to minimal info
            rows.append({
                "Function Name": name,
                "Number of Arguments": None,
                "Defaults": json.dumps({}),
                "Annotations": json.dumps({}),
                "Is Lambda": (name == "<lambda>")
            })
            continue

        params = sig.parameters

        # Count parameters excluding *args (VAR_POSITIONAL) and **kwargs (VAR_KEYWORD)
        num_args = sum(
            1
            for p in params.values()
            if p.kind not in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)
        )

        # Defaults: param name -> repr(default)
        defaults = {
            pname: repr(p.default)
            for pname, p in params.items()
            if p.default is not inspect._empty
        }

        # Annotations: param name -> stringified annotation; include 'return' if present
        annotations = {}
        for pname, p in params.items():
            if p.annotation is not inspect._empty:
                # inspect.formatannotation returns a readable string for annotations
                try:
                    annotations[pname] = inspect.formatannotation(p.annotation)
                except Exception:
                    # fallback to repr if formatting fails
                    annotations[pname] = repr(p.annotation)

        if sig.return_annotation is not inspect._empty:
            try:
                annotations["return"] = inspect.formatannotation(sig.return_annotation)
            except Exception:
                annotations["return"] = repr(sig.return_annotation)

        is_lambda = (name == "<lambda>")

        rows.append({
            "Function Name": name,
            "Number of Arguments": num_args,
            "Defaults": json.dumps(defaults, ensure_ascii=False),
            "Annotations": json.dumps(annotations, ensure_ascii=False),
            "Is Lambda": is_lambda
        })

    # If there are no rows, create an empty DataFrame with the correct columns to produce an empty CSV
    if not rows:
        df = pl.DataFrame({
            "Function Name": pl.Series([], dtype=pl.Utf8),
            "Number of Arguments": pl.Series([], dtype=pl.Int64),
            "Defaults": pl.Series([], dtype=pl.Utf8),
            "Annotations": pl.Series([], dtype=pl.Utf8),
            "Is Lambda": pl.Series([], dtype=pl.Boolean),
        })
    else:
        df = pl.DataFrame(rows)

    # Write to CSV (overwrites existing file_path)
    df.write_csv(file_path)

