from typing import Any, Dict
import httpx
from unidecode import unidecode

def get_github_user_normalized(username: str) -> Dict[str, Any]:
    """
    Retrieve GitHub user info for `username`, normalize all string data to ASCII, and return
    a dictionary of the normalized data.

    Uses the GitHub public API: https://api.github.com/users/{username}

    Raises:
      ValueError: if username is not a non-empty string
      RuntimeError: for network or HTTP errors from the GitHub API

    Example:
      data = get_github_user_normalized("mojombo")
    """
    if not isinstance(username, str) or not username.strip():
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"
    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "get_github_user_normalized/1.0"
    }

    try:
        resp = httpx.get(url, headers=headers, timeout=10.0)
        resp.raise_for_status()
    except httpx.HTTPStatusError as exc:
        # Provide the HTTP status and message for easier debugging
        raise RuntimeError(f"GitHub API returned {exc.response.status_code}: {exc.response.text}") from exc
    except httpx.RequestError as exc:
        raise RuntimeError(f"Network error while contacting GitHub API: {exc}") from exc

    data = resp.json()

    def _normalize(obj: Any) -> Any:
        """Recursively normalize all strings in obj to ASCII using unidecode."""
        if isinstance(obj, str):
            return unidecode(obj)
        if isinstance(obj, bytes):
            # decode bytes then transliterate
            try:
                s = obj.decode("utf-8", errors="replace")
            except Exception:
                s = str(obj)
            return unidecode(s)
        if isinstance(obj, dict):
            normalized_dict = {}
            for k, v in obj.items():
                # normalize string keys as well (convert to ASCII string)
                norm_key = unidecode(k) if isinstance(k, str) else k
                normalized_dict[norm_key] = _normalize(v)
            return normalized_dict
        if isinstance(obj, list):
            return [_normalize(i) for i in obj]
        if isinstance(obj, tuple):
            return tuple(_normalize(i) for i in obj)
        if isinstance(obj, set):
            # sets are converted to lists to preserve JSON-serializable structure
            return [_normalize(i) for i in obj]
        # leave other types (int, float, bool, None) unchanged
        return obj

    normalized = _normalize(data)

    # Ensure the returned type is a dict (GitHub user endpoint returns JSON object)
    if not isinstance(normalized, dict):
        raise RuntimeError("Unexpected response format from GitHub API")

    return normalized

