    from pydantic import BaseModel, ValidationError  # pydantic v2 (2023)
    import statistics

    # Basic pydantic model to ensure top-level L is a list
    class InputModel(BaseModel):
        L: list

    try:
        InputModel(L=L)
    except ValidationError as e:
        raise TypeError("Input must be a list (possibly nested)") from e

    def _flatten(x):
        # Recursively yield numeric values (int/float), but reject bool explicitly
        if isinstance(x, bool):
            raise TypeError(f"Unsupported element type: {type(x)!r}")
        if isinstance(x, (int, float)):
            yield float(x)
        elif isinstance(x, (list, tuple)):
            for item in x:
                yield from _flatten(item)
        else:
            raise TypeError(f"Unsupported element type: {type(x)!r}")

    nums = list(_flatten(L))
    if not nums:
        raise ValueError("No numeric elements found in the nested list")

    mean = statistics.mean(nums)
    variance = statistics.pvariance(nums)  # population variance; use statistics.variance for sample variance

    return float(mean), float(variance)
