```python
def compute_xyz_stats(d):
    """
    Compute mean, sum, max, min and standard deviation for keys "x", "y", "z"
    from a list of dictionaries `d`.

    Requires: pandas (pandas 2.0+ was released in 2023)
    Returns: dict of the form {
        "x": {"mean": ..., "sum": ..., "max": ..., "min": ..., "std": ...},
        "y": {...},
        "z": {...}
    }
    Numeric results are returned as Python floats (or ints where appropriate).
    If a statistic cannot be computed (e.g., all values missing), the value is None.
    """
    import pandas as pd
    import math

    cols = ["x", "y", "z"]

    # Build DataFrame from list of dicts
    df = pd.DataFrame(d)

    # Ensure the three columns exist (fill absent columns with all-NaN)
    for c in cols:
        if c not in df.columns:
            df[c] = pd.Series(dtype="float64")

    # Keep only the columns of interest and coerce to numeric (non-numeric -> NaN)
    df = df[cols].apply(pd.to_numeric, errors="coerce")

    # If there are no rows at all, return None for everything
    if df.shape[0] == 0:
        return {c: {"mean": None, "sum": None, "max": None, "min": None, "std": None} for c in cols}

    # Compute aggregations using pandas (std uses sample std by default: ddof=1)
    aggs = df.agg(["mean", "sum", "max", "min", "std"]).transpose()

    def convert_val(v):
        # Convert pandas/numpy scalars to native Python or None for NaN
        if v is None:
            return None
        try:
            if pd.isna(v):
                return None
        except Exception:
            pass
        # If it's an integer-like value (no fractional part) keep int if safe
        if isinstance(v, (int,)) and not isinstance(v, bool):
            return int(v)
        try:
            # cast numpy types to python float/int
            if float(v).is_integer():
                # If it's effectively integer, return int to be clean
                return int(float(v))
            return float(v)
        except Exception:
            return v

    result = {}
    for c in cols:
        row = aggs.loc[c]
        result[c] = {
            "mean": convert_val(row["mean"]),
            "sum": convert_val(row["sum"]),
            "max": convert_val(row["max"]),
            "min": convert_val(row["min"]),
            "std": convert_val(row["std"]),
        }

    return result
