Here's a self-contained Python function that counts occurrences of values for the keys "x", "y", and "z" from a list of dictionaries d. It uses pydantic v2 (released in 2023) to parse/validate items robustly and collections.Counter to count occurrences.

```python
from typing import Any, Dict, List, Optional
from collections import Counter
from pydantic import BaseModel


class XYZModel(BaseModel):
    x: Optional[Any] = None
    y: Optional[Any] = None
    z: Optional[Any] = None


def count_xyz(d: List[Dict]) -> Dict[str, Dict[Any, int]]:
    """
    Count occurrences of values for keys 'x', 'y', and 'z' in a list of dicts.

    Args:
        d: List of dictionaries to inspect.

    Returns:
        A dict with keys 'x', 'y', 'z', each mapping to a dict of value->count.
        Example:
            {
                'x': {'a': 2, 'b': 1},
                'y': {1: 3},
                'z': {}
            }
    """
    def _hashable_value(v: Any) -> Any:
        # Ensure values used as Counter keys are hashable.
        try:
            hash(v)
            return v
        except TypeError:
            # Fallback: use repr for unhashable values (lists, dicts, etc.)
            return repr(v)

    counters = {'x': Counter(), 'y': Counter(), 'z': Counter()}

    for item in d:
        if not isinstance(item, dict):
            # skip non-dict items
            continue
        # Use pydantic v2 style validation
        try:
            parsed = XYZModel.model_validate(item)
        except Exception:
            # If validation fails for this item, skip it
            continue

        for key in ("x", "y", "z"):
            val = getattr(parsed, key)
            if val is not None:
                counters[key][_hashable_value(val)] += 1

    # Convert Counter objects to plain dicts for the result
    return {k: dict(counters[k]) for k in ("x", "y", "z")}


# Example usage:
if __name__ == "__main__":
    sample = [
        {"x": "a", "y": 1},
        {"x": "a", "y": 2},
        {"x": "b", "y": 1, "z": [1, 2]},
        {"y": 1},
        {"x": None, "y": None},  # None values are ignored
        "not a dict",
        {"z": {"nested": "dict"}}
    ]
    print(count_xyz(sample))
    # Possible output:
    # {'x': {'a': 2, 'b': 1}, 'y': {1: 3, 2: 1}, 'z': {'[1, 2]': 1, "{'nested': 'dict'}": 1}}
```

