from typing import Any, List, Iterable
import numbers
import matplotlib.pyplot as plt

# Use pydantic v2 (released in 2023). We use model_validate which is new in v2.
from pydantic import BaseModel, ValidationError


def extract_and_visualize_json(
    data: Any,
    path: List[str],
    *,
    chart: str = "line",
    figsize: tuple = (8, 4),
    title: str | None = None,
    convert_numeric_strings: bool = True,
) -> List[float]:
    """
    Extract numeric values from a JSON-like structure following a path of keys,
    and visualize them using matplotlib.

    - data: arbitrary JSON-compatible Python object (dicts/lists/primitives).
    - path: list of keys/indices to traverse. Special token "*"
            means "iterate all children at this level".
            For example:
              ["users", "*", "score"]  -> collects every users[i]["score"]
              ["rows", "0", "value"]   -> selects rows[0]["value"] (note index can be string)
    - chart: one of {"line", "bar", "hist", "scatter"}.
    - figsize: matplotlib figure size.
    - title: optional plot title.
    - convert_numeric_strings: if True, strings like "3.14" or "10" are converted to numbers.

    Returns:
      List[float] of extracted numeric values (in traversal order).
    Raises:
      ValueError on invalid inputs or if no numeric data found.
      ValidationError from pydantic if input types are wrong.

    Note: This function uses pydantic v2's BaseModel.model_validate for simple input validation.
    """

    # Simple input validation using pydantic v2
    class _Request(BaseModel):
        data: Any
        path: List[str]
        chart: str

    try:
        _Request.model_validate({"data": data, "path": path, "chart": chart})
    except ValidationError as e:
        # re-raise with clearer message
        raise ValueError(f"Invalid inputs: {e}") from e

    def _try_convert_numeric(x: Any):
        """Return a numeric (int/float) if x is numeric or a numeric string (when enabled), else None."""
        if isinstance(x, numbers.Real) and not isinstance(x, bool):
            # bool is subclass of int: exclude it
            return float(x)
        if convert_numeric_strings and isinstance(x, str):
            try:
                # try int first, then float
                if x.isdigit() or (x.lstrip("-").isdigit()):
                    return float(int(x))
                return float(x)
            except Exception:
                return None
        return None

    def _collect_numeric_leaves(node: Any) -> Iterable[float]:
        """Recursively collect numeric leaves under node."""
        num = _try_convert_numeric(node)
        if num is not None:
            yield num
            return
        # If container, walk children
        if isinstance(node, dict):
            for v in node.values():
                yield from _collect_numeric_leaves(v)
        elif isinstance(node, (list, tuple, set)):
            for item in node:
                yield from _collect_numeric_leaves(item)
        # else: non-numeric leaf -> nothing

    def _traverse(node: Any, tokens: List[str]) -> Iterable[float]:
        """Traverse node according to tokens. When tokens consumed, collect numeric leaves."""
        if not tokens:
            yield from _collect_numeric_leaves(node)
            return

        token = tokens[0]
        rest = tokens[1:]

        if token == "*":
            # iterate all children (dict values or list items)
            if isinstance(node, dict):
                for v in node.values():
                    yield from _traverse(v, rest)
            elif isinstance(node, (list, tuple, set)):
                for item in node:
                    yield from _traverse(item, rest)
            else:
                # Can't expand wildcard on a leaf; nothing to do
                return
            return

        # If node is dict, try token as key
        if isinstance(node, dict):
            if token in node:
                yield from _traverse(node[token], rest)
            else:
                # Also try to interpret token as integer index and see if any dict values are lists
                # e.g., path like ["items", "0", "value"] where "items" is a list inside some dicts;
                # nothing more to do here.
                return
            return

        # If node is list-like, try token as integer index; otherwise try to apply token to each element's dict.
        if isinstance(node, (list, tuple)):
            # try integer index
            try:
                idx = int(token)
            except Exception:
                idx = None

            if idx is not None:
                if -len(node) <= idx < len(node):
                    yield from _traverse(node[idx], rest)
                else:
                    return
            else:
                # token isn't an integer: try to apply token as a key inside each item
                for item in node:
                    if isinstance(item, dict) and token in item:
                        yield from _traverse(item[token], rest)
                    else:
                        # also allow deeper nested traversal on list items
                        yield from _traverse(item, tokens)
            return

        # Not a container we can traverse; nothing to yield
        return

    # Run traversal and collect numbers
    extracted = list(_traverse(data, path))

    if not extracted:
        raise ValueError(f"No numeric data extracted for path {path!r}")

    # Plotting
    plt.figure(figsize=figsize)
    title_text = title or f"Extracted numeric data ({len(extracted)} values) - path: {'/'.join(path)}"

    if chart == "line":
        plt.plot(range(len(extracted)), extracted, marker="o")
        plt.xlabel("index")
        plt.ylabel("value")
    elif chart == "bar":
        plt.bar(range(len(extracted)), extracted)
        plt.xlabel("index")
        plt.ylabel("value")
    elif chart == "hist":
        plt.hist(extracted, bins=min(50, max(5, len(extracted)//2)))
        plt.xlabel("value")
        plt.ylabel("count")
    elif chart == "scatter":
        plt.scatter(range(len(extracted)), extracted)
        plt.xlabel("index")
        plt.ylabel("value")
    else:
        raise ValueError(f"Unsupported chart type: {chart!r}. Choose from 'line','bar','hist','scatter'.")

    plt.title(title_text)
    plt.grid(True)
    plt.tight_layout()
    plt.show()

    return extracted


