def extract_url_title(text: str) -> str:
    """
    Extracts the first URL found in `text`, fetches that web page, and returns its title.
    Returns an error message string if no URL found or if the page could not be fetched / no title found.

    Requires:
      pip install httpx beautifulsoup4

    Example:
      extract_url_title("Check this out: https://www.python.org/about/") 
      -> "Python - About"
    """
    import re
    import httpx
    from bs4 import BeautifulSoup

    # 1) Find a URL-like substring.
    # Prefer explicit scheme or www., otherwise fall back to domain-like patterns.
    url_match = re.search(r'(?i)\b((?:https?://|www\.)[^\s<>"\)\]]+)', text)
    if not url_match:
        # fallback: domain-like pattern (e.g. example.com/path)
        url_match = re.search(r'\b([A-Za-z0-9.-]+\.[A-Za-z]{2,}(?:/[^\s<>"\)\]]*)?)', text)

    if not url_match:
        return "Error: no URL found in input."

    raw_url = url_match.group(1).rstrip('.,;:!?)"]\'')  # trim common trailing punctuation

    # Normalize URL: add scheme if missing
    if raw_url.startswith("www."):
        url = "http://" + raw_url
    elif not re.match(r'(?i)^https?://', raw_url):
        url = "http://" + raw_url
    else:
        url = raw_url

    # 2) Fetch the URL using httpx
    headers = {
        "User-Agent": "url-title-extractor/1.0 (+https://example.org)"
    }
    try:
        resp = httpx.get(url, headers=headers, timeout=10.0, follow_redirects=True)
    except httpx.RequestError as e:
        return f"Error: network error while fetching URL: {str(e)}"
    except Exception as e:
        return f"Error: unexpected error while fetching URL: {str(e)}"

    # Check for successful HTTP status
    if resp.status_code < 200 or resp.status_code >= 300:
        return f"Error: received HTTP {resp.status_code} when fetching URL."

    # 3) Parse the HTML and extract the title
    content_type = resp.headers.get("Content-Type", "")
    # ensure it's HTML-like
    if "html" not in content_type.lower() and not resp.text.strip().startswith("<"):
        return "Error: fetched content does not appear to be an HTML page."

    try:
        soup = BeautifulSoup(resp.text, "html.parser")
    except Exception as e:
        return f"Error: failed to parse HTML: {str(e)}"

    # Try several strategies for title
    title = None
    if soup.title and soup.title.string:
        title = soup.title.string.strip()
    if not title:
        # Open Graph
        og = soup.find("meta", property="og:title")
        if og and og.get("content"):
            title = og["content"].strip()
    if not title:
        # twitter:title
        tw = soup.find("meta", attrs={"name": "twitter:title"})
        if tw and tw.get("content"):
            title = tw["content"].strip()
    if not title:
        # generic meta title/name
        meta_name = soup.find("meta", attrs={"name": "title"})
        if meta_name and meta_name.get("content"):
            title = meta_name["content"].strip()

    if not title:
        return "Error: could not find a page title."

    return title
